def fee_switch_state():
    try:
        with open(os.path.join(DATA, "usde_backing_history.json")) as f:
            h = json.load(f)
        e = h["entries"] if isinstance(h, dict) else h
        now = datetime.fromisoformat(e[-1]["timestamp"].replace("Z", "+00:00"))
        w = [x["total_supply"] for x in e if isinstance(x.get("total_supply"), (int, float))
             and datetime.fromisoformat(x["timestamp"].replace("Z", "+00:00")) > now - timedelta(days=14)]
        ma = statistics.mean(w)
        return {"status": "ok", "cadence": "daily", "as_of": _now_iso(),
                "usde_supply_14d_ma_usd": ma, "points": len(w), "threshold_usd": FEE_SWITCH_THRESHOLD_USD,
                "milestone_met": ma > FEE_SWITCH_THRESHOLD_USD, "threshold_source": FEE_SWITCH_SOURCE,
                "note": "state check only; no governance interpretation"}
    except Exception as ex:  # noqa: BLE001
        return _unavailable(ex, cadence="daily")
